validator:
function validate(input) {
  const [{ Toppings = [] }] = input;
  const names = new Set();
  for (const [name, cost] of Toppings) {
    if (name === null || cost === null) return 'topping_name and cost are required.';
    if (name.includes(',')) return 'A topping name cannot contain a comma.';
    const key = name.toLowerCase();
    if (names.has(key)) return `Topping ${name} appears twice.`;
    names.add(key);
    if (cost < 0 || cost > 999.99) return `The cost of ${name} must be between 0 and 999.99.`;
  }
  return null;
}

