function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // Each word is capitalised, so alphabetical order is the same with or without case.
  const pool = ['Anchovies', 'Artichokes', 'Bacon', 'Basil', 'Beef', 'Black Olives', 'Broccoli', 'Capers', 'Chicken', 'Corn',
    'Eggplant', 'Extra Cheese', 'Feta', 'Garlic', 'Green Peppers', 'Ham', 'Jalapenos', 'Kale', 'Meatballs', 'Mushrooms',
    'Olives', 'Onions', 'Oregano', 'Pepperoni', 'Pesto', 'Pineapple', 'Prosciutto', 'Red Onions', 'Ricotta', 'Salami',
    'Sausage', 'Shrimp', 'Spinach', 'Sun Dried Tomatoes', 'Tomatoes', 'Tuna', 'Zucchini'];
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  // Small cases draw costs from a short list so equal totals (and the pizza tie-break) are common.
  const cheap = [0, 0.25, 0.4, 0.5, 0.55, 0.7, 0.75, 1];
  const count = size === 'small' ? pick(8) : 30;
  const Toppings = pool.slice(0, count).map(name => [name, size === 'small' ? cheap[pick(cheap.length)] : (25 + pick(300)) / 100]);
  return [{ Toppings }];
}
